function main(p, state) {
  var item = String(p.item || '');
  var want = Number(p.count || 1);
  var inv = (state.inventory || {}).slots || [];
  var have = 0;
  for (var i = 0; i < inv.length; i++) {
    var s = inv[i];
    if (s && s.id === item) { have += Number(s.count || 0); }
  }
  var c = state.container || {};
  var type = String(c.type || 'none');
  var slots = c.slots || [];
  var gridFirst = 1;
  var gridLast = 0;
  var gridLastWide = 9;
  var gridLastNarrow = 4;
  if (type === 'crafting') { gridLast = gridLastWide; }
  else if (type === 'inventory') { gridLast = gridLastNarrow; }
  var gridDirty = false;
  var resultItem = '';
  for (var k = 0; k < slots.length; k++) {
    var t = slots[k];
    if (!t || typeof t.slot !== 'number') { continue; }
    if (gridLast >= gridFirst && t.slot >= gridFirst && t.slot <= gridLast) { gridDirty = true; }
    if (type !== 'none' && t.slot === 0) { resultItem = String(t.id || ''); }
  }
  return { done: have >= want, have: have, want: want, gridDirty: gridDirty, resultItem: resultItem };
}
